/* insertImport */

	SELECT currval('swex_account_import_import_id_seq')

INSERT INTO swex_account_import (
	user_id
	,source_filename
	,wizard_id
	,wizard_name
	,server_id
	,unit_count
	,rune_count
	,raw_json
	,crt_user_id
	,crt_date
	,upt_user_id
	,upt_date
) VALUES (
	#{sess_user_id}
	,#{source_filename}
	,#{wizard_id}
	,#{wizard_name}
	,CAST(#{server_id} AS INTEGER)
	,CAST(#{unit_count} AS INTEGER)
	,CAST(#{rune_count} AS INTEGER)
	,CAST(#{raw_json} AS jsonb)
	,#{sess_user_id}
	,CURRENT_TIMESTAMP
	,#{sess_user_id}
	,CURRENT_TIMESTAMP
)

/* insertMonstersBulk */ INSERT INTO swex_monster ( import_id ,unit_id ,master_id ,level ,stars ,attribute ,awaken_level ,is_awakened ) VALUES
( CAST(#{item.import_id} AS BIGINT) ,CAST(#{item.unit_id} AS BIGINT) ,CAST(#{item.master_id} AS INTEGER) ,CAST(#{item.level} AS INTEGER) ,CAST(#{item.stars} AS INTEGER) ,CAST(#{item.attribute} AS INTEGER) ,CAST(#{item.awaken_level} AS INTEGER) ,CAST(#{item.is_awakened} AS INTEGER) )
ON CONFLICT (import_id, unit_id) DO NOTHING

/* insertRunesBulk */ INSERT INTO swex_rune ( import_id ,rune_id ,wizard_id ,occupied_type ,occupied_id ,unit_id ,slot ,set_id ,grade ,level ,rank ,extra ,base_value ,sell_value ,main_stat_type ,main_stat_value ,innate_stat_type ,innate_stat_value ,pri_eff_json ,prefix_eff_json ,substats_json ,raw_json ) VALUES
( CAST(#{item.import_id} AS BIGINT) ,CAST(#{item.rune_id} AS BIGINT) ,CAST(#{item.wizard_id} AS BIGINT) ,CAST(#{item.occupied_type} AS INTEGER) ,CAST(#{item.occupied_id} AS BIGINT) ,CAST(#{item.unit_id} AS BIGINT) ,CAST(#{item.slot} AS INTEGER) ,CAST(#{item.set_id} AS INTEGER) ,CAST(#{item.grade} AS INTEGER) ,CAST(#{item.level} AS INTEGER) ,CAST(#{item.rank} AS INTEGER) ,CAST(#{item.extra} AS INTEGER) ,CAST(#{item.base_value} AS INTEGER) ,CAST(#{item.sell_value} AS INTEGER) ,CAST(#{item.main_stat_type} AS INTEGER) ,CAST(#{item.main_stat_value} AS INTEGER) ,CAST(#{item.innate_stat_type} AS INTEGER) ,CAST(#{item.innate_stat_value} AS INTEGER) ,CAST(#{item.pri_eff_json} AS jsonb) ,CAST(#{item.prefix_eff_json} AS jsonb) ,CAST(#{item.substats_json} AS jsonb) ,CAST(#{item.raw_json} AS jsonb) )
ON CONFLICT (import_id, rune_id) DO NOTHING

